import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Mail, Lock, LogIn, Eye, EyeOff, Wrench } from 'lucide-react';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    const result = await login(email, password);
    if (result.success) navigate('/');
    setLoading(false);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100 py-12 px-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl p-8">
        <div className="text-center">
          <div className="flex justify-center"><div className="bg-blue-100 p-3 rounded-full"><Wrench className="h-12 w-12 text-blue-600" /></div></div>
          <h2 className="mt-4 text-3xl font-bold text-gray-900">Welcome Back</h2>
          <p className="mt-2 text-gray-600">Sign in to your Umukozi account</p>
        </div>
        <form className="mt-8 space-y-5" onSubmit={handleSubmit}>
          <div><label className="block text-sm font-medium text-gray-700 mb-2">Email Address</label>
            <div className="relative"><Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" /><input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="input-field pl-10" placeholder="you@example.com" required /></div>
          </div>
          <div><label className="block text-sm font-medium text-gray-700 mb-2">Password</label>
            <div className="relative"><Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" /><input type={showPassword ? 'text' : 'password'} value={password} onChange={(e) => setPassword(e.target.value)} className="input-field pl-10 pr-10" placeholder="••••••" required /><button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-1/2 transform -translate-y-1/2">{showPassword ? <EyeOff className="h-5 w-5 text-gray-400" /> : <Eye className="h-5 w-5 text-gray-400" />}</button></div>
          </div>
          <button type="submit" disabled={loading} className="btn-primary w-full flex justify-center items-center gap-2"><LogIn className="h-5 w-5" />{loading ? 'Signing in...' : 'Sign in'}</button>
          <p className="text-center text-sm text-gray-600">Don't have an account? <Link to="/register" className="font-medium text-blue-600 hover:text-blue-500">Create an account</Link></p>
        </form>
        <div className="mt-6 p-4 bg-blue-50 rounded-lg">
          <p className="text-sm font-medium text-blue-800 mb-2">Demo Credentials:</p>
          <p className="text-xs text-blue-700">👤 Admin: nizjp123@gmail.com / 123445</p>
          <p className="text-xs text-blue-700">👤 Client: client@example.com / password123</p>
          <p className="text-xs text-blue-700">🔧 Worker: worker@example.com / password123</p>
        </div>
      </div>
    </div>
  );
};

export default Login;
